    biography: "Steven Meersman is a Venture Partner at Contrarian Ventures, based in Belgium. His firm bio states he is a co-founder of Zenobe, where he leads the EV team. He has nearly two decades of experience in battery and energy commodity trading markets, including as Global Head of Deals Desk at Trafigura, managing commercial optimisation and market risk for refineries and more than 30 import and storage terminals across Africa and Central America. He was previously a consultant at Oliver Wyman advising trading houses and utilities, and was an early member of the team that established AES Energy Storage, now Fluence. Contrarian does not publish his education, join year or board seats.",
