    biography: "Christian Miele is a General Partner at Headline, based in Berlin. He has been active in the startup ecosystem since 2010 as an entrepreneur, angel investor and venture capitalist, and invests in B2B software and deep tech. He serves on the board of Auto1 Group and has backed Mistral AI, NUMA, Trawa and Sparetech. From 2019 to 2023 he chaired the German Startup Association, where he helped drive a national overhaul of employee stock ownership rules. He comes from a family of entrepreneurs, his great-grandfather having co-founded Miele, and Handelsblatt named him Investor of the Year in 2021.",
